const page = (title, body) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRUiTIFY Reply helper</title><style>body{font-family:Arial,sans-serif;max-width:640px;margin:24px auto;padding:0 16px;color:#222}textarea,input,select{width:100%;box-sizing:border-box;font-size:16px;padding:10px;border:1px solid #ccd;border-radius:8px}button{background:#1f7a4a;color:#fff;border:0;padding:12px 22px;border-radius:8px;font-size:16px}.box{background:#f3f8f5;padding:12px;border-radius:8px;white-space:pre-wrap}</style></head><body><h2 style="color:#1f5f3f">' + title + '</h2>' + body + '</body></html>';
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');

const q = $('Helper opened').first().json.query || {};
if (q.k !== '<APPROVAL_KEY>') return [{ json: { html: page('Link not valid', '') } }];
const rows = $('Read CRM (list)').all().map(r => r.json).filter(r => r.Instagram);
const order = s => /^Sent|^Replied/.test(s) ? 0 : /^Approved/.test(s) ? 1 : 2;
rows.sort((a, b) => order(a.Status) - order(b.Status));
const opts = rows.map(r => '<option value="' + esc(r.Instagram) + '"' + (q.u === r.Instagram ? ' selected' : '') + '>' + esc(r.Name) + ' (@' + esc(r.Instagram) + ') - ' + esc(r.Status) + '</option>').join('');
const body = '<p style="color:#555">Pick the vendor, paste what they wrote, and get a reply in their language. Nothing is sent - you copy it into Instagram yourself.</p>' +
  '<form method="POST"><input type="hidden" name="k" value="' + esc(q.k) + '"><p><b>Vendor</b><br><select name="u">' + opts + '</select></p>' +
  '<p><b>Their message</b><br><textarea name="m" rows="6" required placeholder="Paste the vendor\'s reply here"></textarea></p>' +
  '<p><b>Anything you want the reply to say?</b> (optional, in English)<br><input name="h" placeholder="e.g. ask for a call tomorrow 5 pm"></p><button>Draft my reply</button></form>';
return [{ json: { html: page('Reply helper', body) } }];

const SYSTEM = "You are helping Ankur, founder of FRUiTIFY (fruitifyindia.com, run by Expert Resourcing Pvt. Ltd., Gurugram), reply to an Instagram fruit seller who answered his outreach. Ankur sends every message himself; you only draft.

FACTS YOU MAY USE (never invent anything else):
- FRUiTIFY gives a fruit seller their own online fruit shop with its own link (like theirshop.fruitifyindia.com) to share on Instagram, WhatsApp and with regular customers.
- Customers open the link, pick fruits and order themselves - no long WhatsApp lists, no missed calls. Fruit is charged by exact weight. Orders come from the seller's own known shop.
- The seller's team gets screens for adding fruits and prices, stock, orders, delivery partners and simple business reports.
- Offer: 2 MONTHS FREE TRIAL, then a paid plan. The plan is agreed case by case with Ankur (a subscription or a revenue share) - never quote a price; never use the words "bilkul free", "free forever" or "lifetime free" (say "2 mahine ka free trial" or the same in their language); say Ankur will explain the plan on a call.
- Ankur's team helps with the setup. Do not promise how many minutes or days it takes.
- Contact: WhatsApp or call +91 96117 01149.
- Never name any competitor app or company. Never claim cold-chain, delivery times, guarantees, or anything not listed here. If the seller asks something you cannot answer from these facts, say Ankur will confirm it on a call.

HOW TO REPLY:
- Reply in the seller's language written in that language's OWN native script - Hindi or Hinglish in Devanagari, Tamil in Tamil script, Gujarati in Gujarati script, and so on - even if they typed in English/Roman letters. NEVER reply in English and NEVER write an Indian language in Roman letters. Only FRUiTIFY, the phone number and the app names WhatsApp and Instagram may stay in English letters. Write EVERY other word in the language's own script, including English loan words (e.g. in Hindi: ऑनलाइन, ऑर्डर, लिंक, फ्री ट्रायल, पेड प्लान, डिलीवरी, सेटअप; never online, order, link, free trial in Roman letters); do the same in every other script. Warm, respectful, short (25-70 words), like a real shop owner chatting. At most one emoji.
- Answer their actual question or concern first. Then move them one step forward: usually ask for a good time for a short call, or their WhatsApp number, or invite them to WhatsApp +91 96117 01149.
- If they say not interested, thank them politely and close kindly without pushing.
- If the message is rude, spam or unrelated, draft a short polite close.
- Sign off: - Ankur

OUTPUT ONLY these tags:
<reply></reply>
<reply_english></reply_english>
<intent></intent>   (one of: interested, question, wants_call, not_interested, other)
<note_for_ankur></note_for_ankur>   (one short line in English: what they want / what to do next)";
const b = $('Reply submitted').first().json.body || {};
if (b.k !== '<APPROVAL_KEY>') return [{ json: { invalid: true } }];
const row = $('Read CRM').all().map(r => r.json).find(r => String(r.Instagram).toLowerCase() === String(b.u || '').toLowerCase());
if (!row || !String(b.m || '').trim()) return [{ json: { invalid: true } }];
const context = { shop: row.Name, instagram: row.Instagram, region: row.Region, language_we_used: row.Language, bio: row.Bio,
  our_first_message: row['DM pitch'], their_earlier_reply: row['Vendor reply'] || '', our_earlier_draft: row['Next reply draft'] || '' };
const content = 'Seller details and conversation so far:
' + JSON.stringify(context, null, 2) + '

Their NEW message:
' + String(b.m) + (b.h ? '

Ankur wants the reply to: ' + String(b.h) : '');
return [{ json: { u: row.Instagram, name: row.Name, message: String(b.m), earlier: row['Vendor reply'] || '', status: row.Status,
  claudeRequest: { model: 'claude-sonnet-5-5', max_tokens: 3000, output_config: { effort: 'low' }, system: SYSTEM, messages: [{ role: 'user', content }] } } }];

const d = $('Prepare reply request').first().json;
const raw = ($input.first().json.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
const t = k => { const m = raw.match(new RegExp('<' + k + '>([\\s\\S]*?)</' + k + '>')); return m ? m[1].trim() : ''; };
const now = $now.setZone('Asia/Kolkata').toFormat('d LLL HH:mm');
const log = (d.earlier ? d.earlier + '\n---\n' : '') + '[' + now + '] ' + d.message;
const statusByIntent = { not_interested: 'Not interested', wants_call: 'Replied - wants a call', interested: 'Replied - interested', question: 'Replied - has questions' };
return [{ json: { ...d, reply: t('reply'), reply_english: t('reply_english'), intent: t('intent'), note: t('note_for_ankur'), log,
  newStatus: statusByIntent[t('intent')] || 'Replied - draft ready' } }];

const page = (title, body) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRUiTIFY Reply helper</title><style>body{font-family:Arial,sans-serif;max-width:640px;margin:24px auto;padding:0 16px;color:#222}textarea,input,select{width:100%;box-sizing:border-box;font-size:16px;padding:10px;border:1px solid #ccd;border-radius:8px}button{background:#1f7a4a;color:#fff;border:0;padding:12px 22px;border-radius:8px;font-size:16px}.box{background:#f3f8f5;padding:12px;border-radius:8px;white-space:pre-wrap}</style></head><body><h2 style="color:#1f5f3f">' + title + '</h2>' + body + '</body></html>';
const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');

const d = $('Prepare reply request').first().json;
if (d.invalid) return [{ json: { html: page('Could not draft', '<p>The link or the vendor was not valid, or the message was empty.</p>') } }];
const r = $('Read draft').first().json;
const body = '<p><b>' + esc(r.name) + '</b> (@' + esc(r.u) + ') &middot; ' + esc(r.newStatus) + '</p><p style="color:#a15c00"><b>Note:</b> ' + esc(r.note) + '</p>' +
  '<p><b>Your reply</b></p><div class="box" id="rep">' + esc(r.reply) + '</div>' +
  '<p><button onclick="navigator.clipboard.writeText(document.getElementById(\'rep\').innerText).then(()=>{this.innerText=\'Copied\'})">Copy reply</button> &nbsp; <a href="https://ig.me/m/' + encodeURIComponent(r.u) + '" style="font-size:16px">Open their Instagram chat</a></p>' +
  '<p style="color:#555;font-size:14px"><b>In English:</b> ' + esc(r.reply_english) + '</p>' +
  '<p style="font-size:13px;color:#888">Saved in the CRM sheet. <a href="?k=<APPROVAL_KEY>&u=' + encodeURIComponent(r.u) + '">Draft another reply</a></p>';
return [{ json: { html: page('Reply ready', body) } }];
